class CloudaiFusion < Formula
  desc "Cloud-Native AI Unified Management Platform — multi-cloud, GPU scheduling, AI Ops"
  homepage "https://github.com/cloudai-fusion/cloudai-fusion"
  license "Apache-2.0"
  version "${VERSION}"        # replaced by GoReleaser

  on_macos do
    if Hardware::CPU.arm?
      url "https://github.com/cloudai-fusion/cloudai-fusion/releases/download/v${VERSION}/cloudai-fusion_${VERSION}_darwin_arm64.tar.gz"
      sha256 "${SHA256_DARWIN_ARM64}"
    else
      url "https://github.com/cloudai-fusion/cloudai-fusion/releases/download/v${VERSION}/cloudai-fusion_${VERSION}_darwin_amd64.tar.gz"
      sha256 "${SHA256_DARWIN_AMD64}"
    end
  end

  on_linux do
    if Hardware::CPU.arm?
      url "https://github.com/cloudai-fusion/cloudai-fusion/releases/download/v${VERSION}/cloudai-fusion_${VERSION}_linux_arm64.tar.gz"
      sha256 "${SHA256_LINUX_ARM64}"
    else
      url "https://github.com/cloudai-fusion/cloudai-fusion/releases/download/v${VERSION}/cloudai-fusion_${VERSION}_linux_amd64.tar.gz"
      sha256 "${SHA256_LINUX_AMD64}"
    end
  end

  def install
    bin.install "cloudai-apiserver"
    bin.install "cloudai-scheduler"
    bin.install "cloudai-agent"

    # Install shell completions
    generate_completions_from_executable(bin/"cloudai-apiserver", "completion")
  end

  test do
    assert_match version.to_s, shell_output("#{bin}/cloudai-apiserver --version 2>&1", 0)
  end
